<script>
(function(){"use strict";const $=id=>document.getElementById(id);const n=id=>Number($(id).value)||0;const fmt=v=>(Math.round((Number(v)||0)*100)/100).toLocaleString('el-GR',{minimumFractionDigits:2,maximumFractionDigits:2});
function academic(){const grade=n('degreeGrade');const valid=$('degreeGrade').value!==''&&grade>=5&&grade<=10;const degree=valid?Math.round(grade*2.5*100)/100:0;const masters=n('masters')===1?20:n('masters')>=2?28:0;const raw=degree+($('secondDegree').checked?7:0)+($('phd').checked?40:0)+masters+n('lang1')+n('lang2')+($('computer').checked?4:0)+($('training').checked?2:0);return{degree,raw,points:Math.min(raw,120),valid,masters};}
function service(){const m=v=>Math.max(0,Math.floor(Number(v)||0));const tri=(v,rate,cap)=>({months:m(v),points:Math.min(m(v)*rate,cap)});const parts=[EducationService.regularPublic(n('publicMonths')),EducationService.difficult(n('hardMonths')),tri(n('covid2020'),1.5,10),tri(n('covid2021'),1.5,10),tri(n('covidHard2020'),3,20),tri(n('covidHard2021'),3,20)];const raw=parts.reduce((s,x)=>s+x.points,0),months=parts.reduce((s,x)=>s+x.months,0);return{raw,points:Math.min(raw,120),months};}
function social(){return EducationSocial.calculate({children:n('children'),candidateDisability:n('candidateDisability'),spouseDisability:n('spouseDisability'),childDisability:n('childDisability'),candidateMentalCondition:$('mental').checked,marriageYears4Plus:$('marriage4').checked});}
function branchUI(){const b=$('branch').value;const note=$('branchNote'),sn=$('serviceBranchNote');$('pe23Wrap').classList.toggle('hidden',b!=='PE23');$('formalMasterNote').classList.toggle('hidden',!['PE21','PE22','PE31'].includes(b));let t='Επίλεξε κλάδο για να εμφανιστούν οι ειδικές επισημάνσεις.';if(b==='PE23')t='<strong>ΠΕ23:</strong> η εξειδίκευση στη Σχολική Ψυχολογία δημιουργεί πρόταξη. Η Παιδαγωγική/Διδακτική Επάρκεια καθορίζει περαιτέρω τη σειρά μέσα στις ομάδες πρόταξης.';else if(b==='PE25')t='<strong>ΠΕ25:</strong> προϋπηρεσία αναπληρωτή εκπαιδευτικού ΠΕ87.02-Νοσηλευτικής που αποκτήθηκε με τις ειδικές διατάξεις της προκήρυξης προσμετράται και στον ΠΕ25.';else if(['PE21','PE22'].includes(b))t='<strong>'+b+':</strong> όταν μεταπτυχιακός τίτλος αποτελεί τυπικό προσόν διορισμού, δεν μοριοδοτείται και η προϋπηρεσία προσμετράται μετά την κτήση του.';else if(b==='PE31')t='<strong>ΠΕ31:</strong> όταν μεταπτυχιακός τίτλος αποτελεί τυπικό προσόν διορισμού, δεν μοριοδοτείται και η προϋπηρεσία προσμετράται μετά την κτήση του. Επαγγελματική εμπειρία τριών ετών που αποτελεί τυπικό προσόν δεν μοριοδοτείται.';else if(b)t='Για τον '+b+' εφαρμόζεται ο κοινός πίνακας μοριοδότησης ΕΕΠ. Η Παιδαγωγική/Διδακτική Επάρκεια αποτελεί κριτήριο πρόταξης.';note.innerHTML=t;let st='Η ειδική μοριοδότηση ιδιωτικής σχολικής προϋπηρεσίας με συντελεστή 0,9 δεν αφορά τα μέλη ΕΕΠ-ΕΒΠ.';if(b==='PE25')st+='<br><strong>ΠΕ25:</strong> έλεγξε και τυχόν επιλέξιμη προϋπηρεσία ΠΕ87.02-Νοσηλευτικής.';if(['PE21','PE22','PE31'].includes(b))st+='<br><strong>'+b+':</strong> αν ο μεταπτυχιακός είναι τυπικό προσόν διορισμού, δήλωσε μόνο προϋπηρεσία μετά την κτήση του.';if(b==='PE31')st+='<br>Μην περιλάβεις την τριετή επαγγελματική εμπειρία όταν αυτή αποτελεί τυπικό προσόν διορισμού.';sn.innerHTML=st;$('schoolPsychReminder').classList.toggle('hidden',!(b==='PE23'&&$('schoolPsych').value==='degree'));}
function priority(){const b=$('branch').value,ped=$('pedagogical').checked,pb=$('priorityBox');pb.className='priority';if(!b){pb.textContent='Επίλεξε κλάδο για έλεγχο πρόταξης';}else if(b==='PE23'){const spec=$('schoolPsych').value!=='none';pb.className='priority '+(spec?'special':ped?'yes':'');if(spec&&ped)pb.textContent='ΠΕ23 — Ομάδα πρόταξης 1: εξειδίκευση Σχολικής Ψυχολογίας + ΠΔΕ';else if(spec)pb.textContent='ΠΕ23 — Ομάδα πρόταξης 2: εξειδίκευση Σχολικής Ψυχολογίας χωρίς ΠΔΕ';else if(ped)pb.textContent='ΠΕ23 — Ομάδα πρόταξης 3: χωρίς εξειδίκευση, με ΠΔΕ';else pb.textContent='ΠΕ23 — Ομάδα 4: χωρίς εξειδίκευση και χωρίς ΠΔΕ';}else{pb.className='priority'+(ped?' yes':'');pb.textContent=ped?'Πρόταξη λόγω Παιδαγωγικής και Διδακτικής Επάρκειας':'Χωρίς δηλωμένη πρόταξη Παιδαγωγικής/Διδακτικής Επάρκειας';}const sp=$('specialPriorityBox');const extras=[];if($('braille').checked)extras.push('Braille — προτεραιότητα για μαθητές με προβλήματα όρασης');if($('signLanguage').checked)extras.push('ΕΝΓ — προτεραιότητα για κωφούς/βαρήκοους μαθητές');sp.textContent=extras.join(' · ');sp.className='priority special'+(extras.length?'':' hidden');}
function render(){branchUI();const a=academic(),s=service(),c=social(),total=a.points+s.points+c.total;$('gradeWarning').classList.toggle('hidden',$('degreeGrade').value===''||a.valid);$('academicSubtotal').textContent=fmt(a.points);$('serviceSubtotal').textContent=fmt(s.points);$('socialSubtotal').textContent=fmt(c.total);$('totalPoints').textContent=fmt(total);$('degreePoints').textContent=fmt(a.degree);$('academicPoints').textContent=fmt(a.points)+(a.raw>120?' (όριο 120)':'');$('servicePoints').textContent=fmt(s.points)+(s.raw>120?' (όριο 120)':'');$('socialPoints').textContent=fmt(c.total);const sw=$('serviceWarning');const msgs=[];if(s.months>120)msgs.push('Έχουν δηλωθεί '+s.months+' μήνες σε ξεχωριστές κατηγορίες. Έλεγξε ότι δεν έχει δηλωθεί ο ίδιος μήνας δύο φορές και ότι η συνολική πραγματική προϋπηρεσία δεν υπερβαίνει τους 120 μήνες που λαμβάνονται υπόψη.');if(s.raw>120)msgs.push('Η μοριοδότηση προϋπηρεσίας περιορίστηκε στο ανώτατο όριο των 120 μορίων.');sw.textContent=msgs.join(' ');sw.classList.toggle('hidden',msgs.length===0);const soc=$('socialWarning');soc.textContent=c.warnings.join(' ');soc.classList.toggle('hidden',c.warnings.length===0);priority();return{a,s,c,total};}
function summary(r){return`Υπολογισμός μορίων 2ΕΑ/2025 — ${$('branch').value||'κλάδος μη επιλεγμένος'}\nΒαθμός πτυχίου: ${fmt(r.a.degree)}\nΑκαδημαϊκά: ${fmt(r.a.points)}\nΠροϋπηρεσία: ${fmt(r.s.points)}\nΚοινωνικά: ${fmt(r.c.total)}\nΣΥΝΟΛΟ: ${fmt(r.total)}\nΠρόταξη: ${$('priorityBox').textContent}${$('specialPriorityBox').classList.contains('hidden')?'':'\nΕιδική προτεραιότητα: '+$('specialPriorityBox').textContent}`;}
document.addEventListener('input',render);document.addEventListener('change',render);$('copyBtn').addEventListener('click',async()=>{const txt=summary(render());try{await navigator.clipboard.writeText(txt);$('copyBtn').textContent='Αντιγράφηκε';setTimeout(()=>$('copyBtn').textContent='Αντιγραφή',1200)}catch(e){alert(txt)}});$('resetBtn').addEventListener('click',()=>{document.querySelectorAll('input[type=number]').forEach(x=>x.value=x.id==='degreeGrade'?'':'0');document.querySelectorAll('input[type=checkbox]').forEach(x=>x.checked=false);document.querySelectorAll('select').forEach(x=>x.selectedIndex=0);render();});render();})();
</script>
